// 节点地址（x86_64 示例）
// root  @ 0x1A3F00  // cache line 128
// left  @ 0x8B2000  // cache line 4096
// l->l  @ 0x4C0100  // cache line 2048
Node *p = root;      // miss，加载 line 128
p = p->left;         // miss，加载 line 4096
p = p->left;         // miss，加载 line 2048
// 3 次跳转，3 次 cache miss，预取失效"}}, "right": {"caption": "数组实现（连续存储）", "block": {"type": "code", "language": "c", "code": "int tree[1024];      // 连续基址 0x10000
// 隐式完全二叉树：根 0，左子 2*i+1
int i = 0;           // tree[0] @ 0x10000
i = 2 * i + 1;       // tree[1] @ 0x10004
i = 2 * i + 1;       // tree[3] @ 0x1000C
// 3 次访问，同一 cache line
// 硬件预取直接生效"}}}

